insert into public.events (site, slug, title, badge, date_text, location, image_url, summary, description, link_text, link_url, published, position)
  values ($t$asasul$t$, $t$vida-plena$t$, $t$Encontro Vida Plena$t$, $t$Seminário$t$, $t$29 e 30 de agosto$t$, $t$San Marco Brasília Hotel$t$, $t$https://brasilia.comshalom.org/asasul/images/eventos/vida-plena.jpeg$t$, $t$Liderança, crescimento, resultados… Onde encontrar propósito e plenitude em meio a tantos desafios?$t$, $t$<p>💼✨ Liderança, crescimento, resultados… Onde encontrar propósito e plenitude em meio a tantos desafios?</p><p>🌿 O Encontro Vida Plena é uma experiência com o Amor de Deus, promovido pelo Projeto Mundo Novo da Comunidade Católica Shalom, para profissionais e líderes que desejam integrar fé, vida e missão.</p><p>💫 Dois dias para aprofundar a experiência com Deus, redescobrir a vocação e encontrar um sentido mais profundo para a vida, a família e o trabalho.</p><p>🎤 Carmadélio Sousa (Fortaleza/CE) – Missionário e especialista em relações interpessoais.</p><p>🗓️ 29 e 30 de agosto<br>📍 San Marco Brasília Hotel<br>📲 Informações: (61) 99687-7406<br>👉 Inscrições: <a href="https://forms.gle/y8RxBSaj2KEAuqFNA" target="_blank" rel="noopener">https://forms.gle/y8RxBSaj2KEAuqFNA</a></p><p>📖 &quot;Conhecereis também o amor de Cristo, que ultrapassa todo conhecimento, para que sejais repletos de toda a plenitude de Deus.&quot; (Ef 3,19)</p>$t$, $t$Inscrições$t$, $t$https://forms.gle/y8RxBSaj2KEAuqFNA$t$, true, 0)
  on conflict (site, slug) do nothing;
insert into public.events (site, slug, title, badge, date_text, location, image_url, summary, description, link_text, link_url, published, position)
  values ($t$asasul$t$, $t$kyrios$t$, $t$Grupo de Oração Kyrios$t$, $t$Grupo de oração$t$, $t$Todo sábado às 15h$t$, $t$Shalom Asa Sul (507 Sul)$t$, $t$https://brasilia.comshalom.org/asasul/images/eventos/kyrios.jpeg$t$, $t$Um grupo de oração para jovens de 16 a 23 anos que querem viver a fé com intensidade.$t$, $t$<p>Kyrios é o grupo de oração da juventude no Shalom Asa Sul. Um espaço para louvar, rezar e caminhar em comunidade.</p><p>Para quem é: jovens de 16 a 23 anos.<br>Quando: todo sábado, às 15h.<br>Onde: Shalom Asa Sul — 507 Sul.</p><p>Uma iniciativa do Projeto Juventude para Jesus • Comunidade Católica Shalom. Venha e traga um amigo.</p>$t$, null, null, true, 1)
  on conflict (site, slug) do nothing;
