  values ($t$asasul$t$, $t$amare$t$, $t$Grupo de Oração Aberto — Amare$t$, $t$Grupo de oração$t$, $t$Toda quinta-feira às 19h30$t$, $t$Shalom Asa Sul, 507 Sul$t$, $t$https://brasilia.comshalom.org/asasul/images/eventos/amare.jpeg$t$, $t$Um grupo de oração aberto a todos. Venha amar e ser amado na presença de Deus.$t$, $t$<p>Amare é o grupo de oração aberto do Shalom Asa Sul — todos são bem-vindos, sem exceção.</p><p>Quando: toda quinta-feira, às 19h30.<br>Onde: Shalom Asa Sul, 507 Sul.<br>Contato: (61) 98210-8676.</p><p>Entre no grupo do WhatsApp para receber os avisos e caminhar conosco.</p>$t$, $t$Entrar no grupo do WhatsApp$t$, $t$https://wa.me/5561982108676$t$, true, 2)
  on conflict (site, slug) do nothing;
insert into public.events (site, slug, title, badge, date_text, location, image_url, summary, description, link_text, link_url, published, position)
  values ($t$asasul$t$, $t$missa-misericordia$t$, $t$Missa da Misericórdia$t$, $t$Missa especial$t$, $t$Quinta-feira, 30/07$t$, $t$Shalom Asa Sul$t$, $t$https://brasilia.comshalom.org/asasul/images/eventos/missa-misericordia.jpeg$t$, $t$Uma tarde inteira de oração, aconselhamento, confissão e Santa Missa no Shalom Asa Sul.$t$, $t$<p>A Missa da Misericórdia é um dia dedicado a reencontrar o amor misericordioso de Deus.</p><p>Programação — quinta-feira, 30/07:<br>• 14h30 — Oração e aconselhamento<br>• 18h00 — Confissão<br>• 19h30 — Santa Missa</p><p>Onde: Shalom Asa Sul. Traga suas intenções e viva esse encontro com a Misericórdia.</p>$t$, null, null, true, 3)
  on conflict (site, slug) do nothing;
insert into public.events (site, slug, title, badge, date_text, location, image_url, summary, description, link_text, link_url, published, position)
  values ($t$asasul$t$, $t$beraka-casais$t$, $t$Beraká — Retiro para casais$t$, $t$Retiro para casais$t$, $t$26 e 27 de setembro de 2026$t$, $t$SGAS 606, Bloco D, Lote 42 — Brasília/DF$t$, $t$https://brasilia.comshalom.org/asasul/images/eventos/beraka-casais.webp$t$, $t$Um retiro para casais fortalecerem a vida a dois sobre a rocha que é Jesus.$t$, $t$<p>BERAKÁ — Retiro para casais</p><p>Jesus é a rocha onde edifico a minha casa. (Mateus 7,24)</p><p>Quando: 26 e 27 de setembro de 2026.<br>Onde: SGAS 606, Bloco D, Lote 42 — Brasília/DF.<br>Público: casais.</p><p>Enquanto os casais vivem o retiro, o Beraká Kids oferece uma programação própria e simultânea para crianças de 5 a 10 anos.</p><p>Informações:<br>William: (21) 98875-0530<br>Viviane: (61) 99399-0480<br>Instagram: @shalombrasilia<br>Instagram: <a href="https://www.instagram.com/shalombrasilia/" target="_blank" rel="noopener">https://www.instagram.com/shalombrasilia/</a></p><p>Realização: Projeto Família Shalom, Comunidade Católica Shalom e Shalom Brasília — 25 anos.</p><p>Inscrições e informações: <a href="https://comshalom.org/beraka/" target="_blank" rel="noopener">https://comshalom.org/beraka/</a></p>$t$, $t$Saiba mais e inscreva-se$t$, $t$https://comshalom.org/beraka/$t$, true, 4)
  on conflict (site, slug) do nothing;
